import { Profile } from './types';
import { parseProfile } from './parser';
export class ProfileService {
  constructor(readonly profile: Profile) {}
  patch(input: unknown): Profile {
    // Validate the entire patch before changing either stored field.
    const { displayName, tags } = parseProfile(input);
    if (displayName.kind === 'set') this.profile.displayName = displayName.value;
    if (tags.kind === 'set') this.profile.tags = tags.value;
    return this.profile;
  }
}
